#include <iostream>
using namespace std;
typedef long long llong;
const int MAXN = 1000010;
const llong MOD = 1000000007;
bool visited[MAXN];

int main() {
    int p, k, inverse_k;
    scanf("%d%d", &p, &k);
    llong result = 1;
    if (k != 0) {
        if (k == 1) result = p;
        for (int i=1; i<p; i++) {
            if ((llong)i * k % p == 1) {
                inverse_k = i;
                break;
            }
        }
        for (int i=1; i<p; i++) {
            if (!visited[i]) {
                visited[i] = true;
                int x = 1;
                int j = (llong)k * i % p;
                int m = inverse_k;
                while (!visited[j]) {
                    visited[j] = true;
                    x++;
                    m = (llong)m * inverse_k % p;
                    j = (llong)k * j % p;
                }
                if (m == 1) result = (llong)result * p % MOD;
            }
        }
    } else {
        for (int i=1; i<p; i++) {
            result = (llong)result * p % MOD;
        }
    }
    cout << result << endl;
    return 0;
}
